UPDATE `category_overrides` SET `category` = CASE `category` WHEN 'FOOD_AND_DRINK' THEN 'FOOD' WHEN 'GENERAL_MERCHANDISE' THEN 'SHOPPING' WHEN 'TRANSPORTATION' THEN 'TRAVEL' WHEN 'RENT_AND_UTILITIES' THEN 'BILLS' WHEN 'HOME_IMPROVEMENT' THEN 'HOUSING' WHEN 'MEDICAL' THEN 'HEALTHCARE' WHEN 'PERSONAL_CARE' THEN 'MISCELLANEOUS' WHEN 'GENERAL_SERVICES' THEN 'MISCELLANEOUS' WHEN 'GOVERNMENT_AND_NON_PROFIT' THEN 'MISCELLANEOUS' WHEN 'BANK_FEES' THEN 'MISCELLANEOUS' WHEN 'PAYMENT_APPS' THEN 'UNCATEGORIZED' WHEN 'INVESTING' THEN 'SAVINGS' WHEN 'NOT_SPENDING' THEN 'TRANSFER' ELSE `category` END WHERE `category` IN ('FOOD_AND_DRINK','GENERAL_MERCHANDISE','TRANSPORTATION','RENT_AND_UTILITIES','HOME_IMPROVEMENT','MEDICAL','PERSONAL_CARE','GENERAL_SERVICES','GOVERNMENT_AND_NON_PROFIT','BANK_FEES','PAYMENT_APPS','INVESTING','NOT_SPENDING');
